#!/usr/bin/env python3
import json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'data/latest.json').read_text(encoding='utf-8')) if (ROOT/'data/latest.json').exists() else {'generated_at':'هنوز اسکن انجام نشده','count':0,'top':[]}

def plan(item):
    name=(item.get('full_name') or '').lower(); path=item.get('best_path') or ''
    if 'ai' in path.lower() or any(x in name for x in ('agent','llm','rag','ai-','-ai','ollama','langchain','openhands','browser-use')):
        return ('ساخت SaaS تخصصی روی هسته پروژه','شرکت‌ها، تیم‌های فنی و کاربران فارسی‌زبان','اشتراک ماهانه + پلن سازمانی + نصب و سفارشی‌سازی','فارسی‌سازی و RTL، رابط ساده، اتصال به سرویس‌های ایرانی و قابلیت‌های بومی','با MVP رایگان شروع کن؛ سپس Pro و Enterprise','بالا')
    if any(x in name for x in ('commerce','shop','store','ecommerce','oscar','aimeos')):
        return ('SaaS فروشگاهی/عمودی یا پکیج فروشگاهی فارسی','فروشگاه‌ها و کسب‌وکارهای آنلاین','اشتراک + هزینه راه‌اندازی + افزونه‌های پولی','درگاه ایرانی، مالیات، فاکتور، پیامک، RTL و تقویم شمسی','فروش سرویس راه‌اندازی سریع و بعد SaaS','بالا')
    return ('سرویس تخصصی، نصب و سفارشی‌سازی','کسب‌وکارها و تیم‌هایی که همان مشکل پروژه را دارند','هزینه نصب + قرارداد پشتیبانی + اشتراک SaaS','فارسی‌سازی، RTL، مستندات، داشبورد و اتصال به سرویس‌های محلی','با خدمات نصب شروع کن و بعد SaaS بساز','متوسط')

cards=[]
for i,x in enumerate(data.get('top',[]),1):
    p=plan(x); desc=html.escape(x.get('description') or 'توضیح تکمیلی در اسکن‌های بعدی استخراج می‌شود.')
    cards.append(f'''<article class="project"><div class="rank">#{i}</div><div class="head"><div><h2><a href="{html.escape(x['url'])}" target="_blank" rel="noopener">{html.escape(x['full_name'])}</a></h2><p class="desc">{desc}</p></div><div class="score">{x['score']}<small>/100</small></div></div><div class="facts"><span>⭐ {x['stars']:,}</span><span>⚖️ {html.escape(x.get('license') or 'نامشخص')}</span><span>💰 {html.escape(x.get('best_path') or 'در حال تحلیل')}</span></div><div class="cols"><section><h3>کاربرد پروژه</h3><p>{desc}</p></section><section><h3>کاربرد برای شما</h3><p>{html.escape(p[0])}</p><p>{html.escape(p[1])}</p></section><section><h3>مدل درآمدی پیشنهادی</h3><p><b>{html.escape(p[2])}</b></p><p>{html.escape(p[3])}</p></section><section><h3>برنامه شروع</h3><p>{html.escape(p[4])}</p><p>ریسک تقریبی: <b>{html.escape(p[5])}</b></p></section></div></article>''')

html_doc=f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="رادار دائمی فرصت‌های درآمدزایی از پروژه‌های متن‌باز گیت‌هاب"><title>رادار فرصت‌های درآمدی متن‌باز</title><style>*{{box-sizing:border-box}}body{{font-family:Tahoma,Arial,sans-serif;margin:0;background:#080d18;color:#e9eef8;line-height:1.8}}main{{max-width:1250px;margin:auto;padding:28px 18px}}header{{background:#111a2b;border:1px solid #263653;border-radius:20px;padding:28px;margin-bottom:20px}}h1{{margin:0 0 8px;font-size:32px}}.sub{{color:#aab7ce}}.stats{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}}.stat{{background:#18233a;padding:18px;border-radius:15px}}.stat b{{font-size:28px;display:block}}.project{{background:#111a2b;border:1px solid #263653;border-radius:18px;padding:20px;margin:16px 0}}.head{{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}}h2{{margin:0;font-size:21px}}a{{color:#8db4ff;text-decoration:none}}.desc{{color:#aab7ce;margin:5px 0}}.score{{font-size:28px;font-weight:bold;white-space:nowrap}}.score small{{font-size:13px;color:#7f8da5}}.rank{{color:#7f8da5;font-weight:bold}}.facts{{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}}.facts span{{background:#18233a;border-radius:999px;padding:5px 11px;color:#c7d2e5;font-size:13px}}.cols{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}section{{background:#0d1525;padding:14px;border-radius:12px}}section h3{{font-size:15px;margin:0 0 7px;color:#dbe7ff}}section p{{margin:4px 0;color:#b8c4d8;font-size:14px}}.note{{color:#8796ae;font-size:12px;margin-top:20px}}@media(max-width:900px){{.cols{{grid-template-columns:repeat(2,1fr)}}}}@media(max-width:600px){{.stats,.cols{{grid-template-columns:1fr}}.head{{display:block}}.score{{margin-top:10px}}}}</style></head><body><main><header><h1>📡 رادار فرصت‌های درآمدی متن‌باز</h1><div class="sub">برای هر پروژه: کاربرد، کاربرد برای شما، روش استفاده، محصول قابل ساخت و مدل درآمدی پیشنهادی.</div><div class="stats"><div class="stat"><b>{data.get('count',0)}</b>پروژه اسکن‌شده</div><div class="stat"><b>{len(data.get('top',[]))}</b>فرصت رتبه‌بندی‌شده</div><div class="stat"><b>روزانه</b>اسکن خودکار</div></div><div class="sub">آخرین بروزرسانی: {html.escape(data.get('generated_at',''))}</div></header><h1>🏆 فرصت‌های برتر</h1>{''.join(cards)}<p class="note">این تحلیل‌ها بر پایه داده‌های عمومی و قواعد کسب‌وکار هستند و تضمین درآمد نیستند. قبل از استفاده تجاری، متن LICENSE، NOTICE و مجوز وابستگی‌های پروژه بررسی شود.</p></main></body></html>'''
out=ROOT/'dashboard'/'index.html';out.parent.mkdir(exist_ok=True);out.write_text(html_doc,encoding='utf-8')
